/// Approval progress of a change the VTA's policy gates on approvals (CONVENTIONS.md
/// §6).
class KeyRoleApprovalState {
  const KeyRoleApprovalState({
    required this.required,
    required this.received,
    this.approvals,
    required this.expiresAt,
  });

  /// Read this payload from a decoded JSON object.
  factory KeyRoleApprovalState.fromJson(Map<String, dynamic> json) =>
      KeyRoleApprovalState(
        required: json['required'] as int,
        received: json['received'] as int,
        approvals: json['approvals'] == null
            ? null
            : (json['approvals'] as List<dynamic>)
                .map(
                    (e) => RecordedApproval.fromJson(e as Map<String, dynamic>))
                .toList(),
        expiresAt: json['expiresAt'] as String,
      );

  /// Distinct approvals the VTA's policy requires.
  final int required;

  /// Distinct approvals recorded so far, the initiator's own included.
  final int received;

  /// The approvals recorded. Custody projection only; omitted from a response to anyone
  /// who is not themselves an eligible approver of this change.
  final List<RecordedApproval>? approvals;

  /// When the preview, and every approval bound to it, stops being usable.
  final String expiresAt;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'required': required,
        'received': received,
        if (approvals != null)
          'approvals': approvals!.map((e) => e.toJson()).toList(),
        'expiresAt': expiresAt,
      };
}

/// One change to a role's key set, from preview to completion. The identifier's
/// history is the authority for what was published; this record adds which change was
/// which and, in the custody projection, who asked, who approved, and why.
class RotationRecord {
  const RotationRecord({
    required this.rotationId,
    required this.role,
    required this.kind,
    required this.state,
    this.predecessors,
    this.successors,
    this.startedInVersionId,
    this.endedInVersionId,
    this.startedAt,
    this.cacheHorizonAt,
    this.activatesAt,
    this.overlapUntil,
    this.autoRetire,
    this.endedAt,
    this.initiatedBy,
    this.approvals,
    this.reason,
    this.ext,
  });

  /// Read this payload from a decoded JSON object.
  factory RotationRecord.fromJson(Map<String, dynamic> json) => RotationRecord(
        rotationId: json['rotationId'] as String,
        role: KeyRole(json['role'] as String),
        kind: RotationKind(json['kind'] as String),
        state: RotationState(json['state'] as String),
        predecessors: json['predecessors'] == null
            ? null
            : (json['predecessors'] as List<dynamic>)
                .map((e) => e as String)
                .toList(),
        successors: json['successors'] == null
            ? null
            : (json['successors'] as List<dynamic>)
                .map((e) => e as String)
                .toList(),
        startedInVersionId: json['startedInVersionId'] as String?,
        endedInVersionId: json['endedInVersionId'] as String?,
        startedAt: json['startedAt'] as String?,
        cacheHorizonAt: json['cacheHorizonAt'] as String?,
        activatesAt: json['activatesAt'] as String?,
        overlapUntil: json['overlapUntil'] as String?,
        autoRetire: json['autoRetire'] as bool?,
        endedAt: json['endedAt'] as String?,
        initiatedBy: json['initiatedBy'] as String?,
        approvals: json['approvals'] == null
            ? null
            : KeyRoleApprovalState.fromJson(
                json['approvals'] as Map<String, dynamic>),
        reason: json['reason'] as String?,
        ext: json['ext'] as Map<String, dynamic>?,
      );

  final String rotationId;
  final KeyRole role;
  final RotationKind kind;
  final RotationState state;

  /// Verification-method identifiers (for `update`, public keys or commitments) leaving
  /// the role.
  final List<String>? predecessors;

  /// Verification-method identifiers (for `update`, public keys or commitments) entering
  /// the role.
  final List<String>? successors;
  final String? startedInVersionId;
  final String? endedInVersionId;
  final String? startedAt;

  /// Planned rotations: the publishing change's cache horizon (CONVENTIONS.md §10.1).
  /// The switch and any retirement happen no earlier.
  final String? cacheHorizonAt;

  /// When the successor becomes `active` and the predecessor `retiring`; never before
  /// `cacheHorizonAt`.
  final String? activatesAt;

  /// Custody projection only. End of the overlap.
  final String? overlapUntil;

  /// Custody projection only. Whether the VTA retires the predecessor itself at
  /// `overlapUntil`.
  final bool? autoRetire;
  final String? endedAt;

  /// Custody projection only. VID of the administrator whose signed request started the
  /// change.
  final String? initiatedBy;
  final KeyRoleApprovalState? approvals;

  /// Custody projection only. The operator's stated reason. Never published.
  final String? reason;
  final Ext? ext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'rotationId': rotationId,
        'role': role.value,
        'kind': kind.value,
        'state': state.value,
        if (predecessors != null) 'predecessors': predecessors!,
        if (successors != null) 'successors': successors!,
        if (startedInVersionId != null)
          'startedInVersionId': startedInVersionId!,
        if (endedInVersionId != null) 'endedInVersionId': endedInVersionId!,
        if (startedAt != null) 'startedAt': startedAt!,
        if (cacheHorizonAt != null) 'cacheHorizonAt': cacheHorizonAt!,
        if (activatesAt != null) 'activatesAt': activatesAt!,
        if (overlapUntil != null) 'overlapUntil': overlapUntil!,
        if (autoRetire != null) 'autoRetire': autoRetire!,
        if (endedAt != null) 'endedAt': endedAt!,
        if (initiatedBy != null) 'initiatedBy': initiatedBy!,
        if (approvals != null) 'approvals': approvals!.toJson(),
        if (reason != null) 'reason': reason!,
        if (ext != null) 'ext': ext!,
      };
}

/// `addKey` — a verification method joins its role's relationship and `keyRoles`.
/// `retireKey` — a verification method leaves its relationship, `keyRoles` and the
/// document. `revokeKey` — a verification method leaves its relationship and
/// `keyRoles`, and stays in `verificationMethod` with `revoked` set to the compromise
/// time (CONVENTIONS.md §9.1). `rotateUpdateKey` — the identifier's update authority
/// moves to a committed routine successor. `commitUpdateKey` — a new routine successor
/// is committed. `replaceRecoveryCommitment` — the recovery commitment changes.
/// `useRecoveryKey` — the change is authorized by the recovery key, which the
/// identifier then reveals.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const DidDocumentChangeOp(String value) {
  static const DidDocumentChangeOp addKey = DidDocumentChangeOp('addKey');
  static const DidDocumentChangeOp retireKey = DidDocumentChangeOp('retireKey');
  static const DidDocumentChangeOp revokeKey = DidDocumentChangeOp('revokeKey');
  static const DidDocumentChangeOp rotateUpdateKey =
      DidDocumentChangeOp('rotateUpdateKey');
  static const DidDocumentChangeOp commitUpdateKey =
      DidDocumentChangeOp('commitUpdateKey');
  static const DidDocumentChangeOp replaceRecoveryCommitment =
      DidDocumentChangeOp('replaceRecoveryCommitment');
  static const DidDocumentChangeOp useRecoveryKey =
      DidDocumentChangeOp('useRecoveryKey');

  /// Every value this specification's schema permits.
  static const List<DidDocumentChangeOp> values = <DidDocumentChangeOp>[
    addKey,
    retireKey,
    revokeKey,
    rotateUpdateKey,
    commitUpdateKey,
    replaceRecoveryCommitment,
    useRecoveryKey
  ];
}

/// DidDocumentChange
class DidDocumentChange {
  const DidDocumentChange({
    required this.op,
    required this.role,
    this.verificationMethod,
    this.keyType,
    this.publicKeyMultibase,
    this.commitment,
    this.relationships,
  });

  /// Read this payload from a decoded JSON object.
  factory DidDocumentChange.fromJson(Map<String, dynamic> json) =>
      DidDocumentChange(
        op: DidDocumentChangeOp(json['op'] as String),
        role: KeyRole(json['role'] as String),
        verificationMethod: json['verificationMethod'] as String?,
        keyType:
            json['keyType'] == null ? null : KeyType(json['keyType'] as String),
        publicKeyMultibase: json['publicKeyMultibase'] as String?,
        commitment: json['commitment'] as String?,
        relationships: json['relationships'] == null
            ? null
            : (json['relationships'] as List<dynamic>)
                .map((e) => DidVerificationRelationship(e as String))
                .toList(),
      );

  /// `addKey` — a verification method joins its role's relationship and `keyRoles`.
  /// `retireKey` — a verification method leaves its relationship, `keyRoles` and the
  /// document. `revokeKey` — a verification method leaves its relationship and
  /// `keyRoles`, and stays in `verificationMethod` with `revoked` set to the compromise
  /// time (CONVENTIONS.md §9.1). `rotateUpdateKey` — the identifier's update authority
  /// moves to a committed routine successor. `commitUpdateKey` — a new routine successor
  /// is committed. `replaceRecoveryCommitment` — the recovery commitment changes.
  /// `useRecoveryKey` — the change is authorized by the recovery key, which the
  /// identifier then reveals.
  final DidDocumentChangeOp op;
  final KeyRole role;
  final String? verificationMethod;
  final KeyType? keyType;
  final String? publicKeyMultibase;
  final String? commitment;
  final List<DidVerificationRelationship>? relationships;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'op': op.value,
        'role': role.value,
        if (verificationMethod != null)
          'verificationMethod': verificationMethod!,
        if (keyType != null) 'keyType': keyType!.value,
        if (publicKeyMultibase != null)
          'publicKeyMultibase': publicKeyMultibase!,
        if (commitment != null) 'commitment': commitment!,
        if (relationships != null)
          'relationships': relationships!.map((e) => e.value).toList(),
      };
}

/// Conditions a human should be shown before approving. `singleKeyRole` — the role
/// will hold one active key. `algorithmNotInAcceptedSet` — a verifier population the
/// VTA knows of does not accept the new key's algorithm. `roleWillHaveNoClassicalKey`
/// — every remaining key is post-quantum. `attestationReissuanceRequired` — revoking
/// this attestation key obliges re-issuance and re-signed status lists (VTI-KEY-133).
/// `selfPublish` — the VTA will not publish the change; the operator must.
/// `noWitnesses` — the identifier has no witnesses, so a party holding the VTA's
/// routine update key can drop the recovery commitment unobserved (CONVENTIONS.md
/// §5.3). `protectionBelowPolicy` — a key will be held at a `ProtectionClass` below
/// what the VTA's policy recommends for its role (a plain VTA holding an attestation
/// key). `recoveryKeyRevealed` — this change uses the recovery key, which must be
/// replaced by a fresh recovery commitment in the same change.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const PreviewWarning(String value) {
  static const PreviewWarning singleKeyRole = PreviewWarning('singleKeyRole');
  static const PreviewWarning algorithmNotInAcceptedSet =
      PreviewWarning('algorithmNotInAcceptedSet');
  static const PreviewWarning roleWillHaveNoClassicalKey =
      PreviewWarning('roleWillHaveNoClassicalKey');
  static const PreviewWarning attestationReissuanceRequired =
      PreviewWarning('attestationReissuanceRequired');
  static const PreviewWarning selfPublish = PreviewWarning('selfPublish');
  static const PreviewWarning noWitnesses = PreviewWarning('noWitnesses');
  static const PreviewWarning protectionBelowPolicy =
      PreviewWarning('protectionBelowPolicy');
  static const PreviewWarning recoveryKeyRevealed =
      PreviewWarning('recoveryKeyRevealed');

  /// Every value this specification's schema permits.
  static const List<PreviewWarning> values = <PreviewWarning>[
    singleKeyRole,
    algorithmNotInAcceptedSet,
    roleWillHaveNoClassicalKey,
    attestationReissuanceRequired,
    selfPublish,
    noWitnesses,
    protectionBelowPolicy,
    recoveryKeyRevealed
  ];
}

/// A file the identifier's method publishes, as the method profile names it
/// (`did.jsonl` for did:webvh, `did.json` and `keri.cesr` for did:webs).
class PublishedArtifact {
  const PublishedArtifact({
    required this.name,
    required this.mediaType,
    required this.content,
  });

  /// Read this payload from a decoded JSON object.
  factory PublishedArtifact.fromJson(Map<String, dynamic> json) =>
      PublishedArtifact(
        name: json['name'] as String,
        mediaType: json['mediaType'] as String,
        content: json['content'] as String,
      );

  final String name;
  final String mediaType;

  /// The artefact's content, or for an append-only artefact the appended part, as text.
  final String content;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'name': name,
        'mediaType': mediaType,
        'content': content,
      };
}

/// How the change reaches resolvers.
class Publication {
  const Publication({
    required this.selfPublish,
    this.artifacts,
  });

  /// Read this payload from a decoded JSON object.
  factory Publication.fromJson(Map<String, dynamic> json) => Publication(
        selfPublish: json['selfPublish'] as bool,
        artifacts: json['artifacts'] == null
            ? null
            : (json['artifacts'] as List<dynamic>)
                .map((e) =>
                    PublishedArtifact.fromJson(e as Map<String, dynamic>))
                .toList(),
      );

  /// True when no hosting service holds the identifier for the VTA: the caller must
  /// publish `artifacts`, and until it does resolvers see the previous version.
  final bool selfPublish;

  /// Present when `selfPublish` is true.
  final List<PublishedArtifact>? artifacts;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'selfPublish': selfPublish,
        if (artifacts != null)
          'artifacts': artifacts!.map((e) => e.toJson()).toList(),
      };
}

/// What a recovery custodian must sign for a change that only the recovery key may
/// authorize (CONVENTIONS.md §5.4, §9.4). The custodian MUST check `unsignedChange`
/// itself — render it to its human, confirm that it reveals the recovery key it holds
/// and commits to a fresh recovery key it also holds — and MUST NOT sign on the
/// strength of this request's description alone.
class RecoverySigningRequest {
  const RecoverySigningRequest({
    required this.commitment,
    required this.keyType,
    required this.unsignedChange,
    required this.proofOptions,
    this.expiresAt,
  });

  /// Read this payload from a decoded JSON object.
  factory RecoverySigningRequest.fromJson(Map<String, dynamic> json) =>
      RecoverySigningRequest(
        commitment: json['commitment'] as String,
        keyType: KeyType(json['keyType'] as String),
        unsignedChange: json['unsignedChange'] as String,
        proofOptions: json['proofOptions'] as Map<String, dynamic>,
        expiresAt: json['expiresAt'] as String?,
      );

  /// The recovery commitment the identifier publishes; the custodian's key MUST be the
  /// one it commits to.
  final String commitment;
  final KeyType keyType;

  /// The change exactly as it will be published, without the recovery proof, as JSON
  /// text in the method's own form (a did:webvh log entry, a KERI rotation event).
  final String unsignedChange;

  /// The proof the method requires over `unsignedChange`, without its signature value,
  /// as the method profile defines it (for did:webvh, a Data Integrity proof
  /// configuration with `proofPurpose: assertionMethod` and the recovery key's `did:key`
  /// as `verificationMethod`).
  final Map<String, dynamic> proofOptions;
  final String? expiresAt;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'commitment': commitment,
        'keyType': keyType.value,
        'unsignedChange': unsignedChange,
        'proofOptions': proofOptions,
        if (expiresAt != null) 'expiresAt': expiresAt!,
      };
}

/// A recovery key offered for commitment (CONVENTIONS.md §5.3). The VTA computes the
/// method's commitment from it, verifies `proofOfPossession`, and then keeps only the
/// commitment. The key MUST be held by a custodian in a protection boundary other than
/// the VTA's; a VTA MUST refuse one it generated or can derive
/// (`vta/dids:recoveryCommitmentRequired`).
class RecoveryCommitment {
  const RecoveryCommitment({
    required this.keyType,
    required this.publicKeyMultibase,
    this.proofOfPossession,
    this.label,
  });

  /// Read this payload from a decoded JSON object.
  factory RecoveryCommitment.fromJson(Map<String, dynamic> json) =>
      RecoveryCommitment(
        keyType: KeyType(json['keyType'] as String),
        publicKeyMultibase: json['publicKeyMultibase'] as String,
        proofOfPossession: json['proofOfPossession'] as String?,
        label: json['label'] as String?,
      );

  final KeyType keyType;

  /// The recovery key's public half. Not published by the VTA where the method commits
  /// by hash.
  final String publicKeyMultibase;

  /// Multibase signature by the recovery key over the UTF-8 bytes of
  /// `vta-dids-recovery-commitment/v1`, a zero byte, and the request's `previewId`.
  /// Absent on a dry run, which is how the `previewId` is obtained; REQUIRED on the
  /// apply request, and the only member besides `previewId`, `dryRun` and
  /// `recoveryProof` that may differ between the two.
  final String? proofOfPossession;

  /// Operator-facing name of the custodian. Custody projection only; never published.
  final String? label;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'keyType': keyType.value,
        'publicKeyMultibase': publicKeyMultibase,
        if (proofOfPossession != null) 'proofOfPossession': proofOfPossession!,
        if (label != null) 'label': label!,
      };
}

/// What a change would publish, computed by the VTA by running the handler it would
/// run to apply it (CONVENTIONS.md §6.1). This is what a consent surface renders and
/// what an approval is bound to.
class DidDocumentPreview {
  const DidDocumentPreview({
    required this.previewId,
    required this.method,
    this.baseVersionId,
    required this.expiresAt,
    required this.changes,
    required this.document,
    this.warnings,
    required this.updateKeyRotates,
    this.recoverySigning,
  });

  /// Read this payload from a decoded JSON object.
  factory DidDocumentPreview.fromJson(Map<String, dynamic> json) =>
      DidDocumentPreview(
        previewId: json['previewId'] as String,
        method: json['method'] as String,
        baseVersionId: json['baseVersionId'] as String?,
        expiresAt: json['expiresAt'] as String,
        changes: (json['changes'] as List<dynamic>)
            .map((e) => DidDocumentChange.fromJson(e as Map<String, dynamic>))
            .toList(),
        document: json['document'] as Map<String, dynamic>,
        warnings: json['warnings'] == null
            ? null
            : (json['warnings'] as List<dynamic>)
                .map((e) => PreviewWarning(e as String))
                .toList(),
        updateKeyRotates: json['updateKeyRotates'] as bool,
        recoverySigning: json['recoverySigning'] == null
            ? null
            : RecoverySigningRequest.fromJson(
                json['recoverySigning'] as Map<String, dynamic>),
      );

  /// Opaque, unguessable identifier of this exact plan. Carried back by the apply
  /// request; every approval and any recovery proof is bound to it.
  final String previewId;
  final DidMethodName method;

  /// The version identifier the plan was computed against. Absent only for a creation.
  /// The plan is void once the identifier moves past it.
  final String? baseVersionId;
  final String expiresAt;

  /// Every change the plan would make, including the ones the caller did not ask for —
  /// in particular any movement of the update authority the method requires.
  final List<DidDocumentChange> changes;

  /// The complete identifier document the change would publish, `keyRoles` included.
  /// Public data by construction.
  final Map<String, dynamic> document;
  final List<PreviewWarning>? warnings;

  /// True when applying the plan also moves the identifier's update authority to a
  /// committed successor — every change under did:webvh pre-rotation, never a KERI
  /// interaction event. Stated as its own member because it is the consequence a
  /// reviewer most often misses.
  final bool updateKeyRotates;
  final RecoverySigningRequest? recoverySigning;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'previewId': previewId,
        'method': method,
        if (baseVersionId != null) 'baseVersionId': baseVersionId!,
        'expiresAt': expiresAt,
        'changes': changes.map((e) => e.toJson()).toList(),
        'document': document,
        if (warnings != null)
          'warnings': warnings!.map((e) => e.value).toList(),
        'updateKeyRotates': updateKeyRotates,
        if (recoverySigning != null)
          'recoverySigning': recoverySigning!.toJson(),
      };
}

/// `preview` — nothing was written; the response carries the plan. `applied` — the
/// change was made (and published, unless `publication.selfPublish`).
/// `pendingApproval` — the plan is recorded and awaits further approvals.
/// `awaitingRecoveryProof` — the plan is approved and waits for the recovery
/// custodian's proof (`preview.recoverySigning`); nothing is published until it
/// arrives.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const KeyRoleChangeOutcome(String value) {
  static const KeyRoleChangeOutcome preview = KeyRoleChangeOutcome('preview');
  static const KeyRoleChangeOutcome applied = KeyRoleChangeOutcome('applied');
  static const KeyRoleChangeOutcome pendingApproval =
      KeyRoleChangeOutcome('pendingApproval');
  static const KeyRoleChangeOutcome awaitingRecoveryProof =
      KeyRoleChangeOutcome('awaitingRecoveryProof');

  /// Every value this specification's schema permits.
  static const List<KeyRoleChangeOutcome> values = <KeyRoleChangeOutcome>[
    preview,
    applied,
    pendingApproval,
    awaitingRecoveryProof
  ];
}

/// The keys an identity is created with in one role (CONVENTIONS.md §4). A key-role
/// DID template carries one per role; a creation request may narrow it but never widen
/// it.
class RoleLayout {
  const RoleLayout({
    required this.role,
    required this.algorithms,
  });

  /// Read this payload from a decoded JSON object.
  factory RoleLayout.fromJson(Map<String, dynamic> json) => RoleLayout(
        role: KeyRole(json['role'] as String),
        algorithms: (json['algorithms'] as List<dynamic>)
            .map((e) => KeyType(e as String))
            .toList(),
      );

  final KeyRole role;

  /// The algorithms to mint, one key each, in publication order — `\["ed25519",
  /// "mldsa44"\]` mints a classical and a post-quantum attestation key that sign as a
  /// proof set. Every entry MUST suit the role (CONVENTIONS.md §2.2). A VTA that cannot
  /// mint one of them MUST refuse the creation with `vta/dids:unsupportedKeyType`; it
  /// never substitutes an algorithm or omits a key.
  final List<KeyType> algorithms;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'role': role.value,
        'algorithms': algorithms.map((e) => e.value).toList(),
      };
}

/// What the node must now do that the change cannot (VTI-KEY-133, CONVENTIONS.md
/// §9.6). Custody data, present when an `attestation` key is revoked or lost.
class ReissuanceFollowUp {
  const ReissuanceFollowUp({
    this.statusListsToResign,
    this.artefactsToReissue,
  });

  /// Read this payload from a decoded JSON object.
  factory ReissuanceFollowUp.fromJson(Map<String, dynamic> json) =>
      ReissuanceFollowUp(
        statusListsToResign: json['statusListsToResign'] as int?,
        artefactsToReissue: json['artefactsToReissue'] as int?,
      );

  /// Status lists signed by the revoked or lost key, which the node MUST re-sign at once
  /// under a sound attestation key.
  final int? statusListsToResign;

  /// Attestation artefacts still in force that the VTA's signing record shows the key
  /// signed, which the node MUST re-issue with identical claims and expiry.
  final int? artefactsToReissue;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        if (statusListsToResign != null)
          'statusListsToResign': statusListsToResign!,
        if (artefactsToReissue != null)
          'artefactsToReissue': artefactsToReissue!,
      };
}
